using System;
using System.Collections.Generic;
using System.IO;
using System.Web.Script.Serialization;
namespace DynastyCOT.Setup {
 internal static class UpdaterChecks {
  static int checks;
  static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;}
  static Dictionary<string,object> Read(string path){return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(path));}
  static Dictionary<string,string> Snapshot(string root){var result=new Dictionary<string,string>();foreach(string file in Directory.GetFiles(root,"*",SearchOption.AllDirectories))if(!file.Contains("\\Backups\\"))using(var input=File.OpenRead(file))result.Add(file.Substring(root.Length),InstallerEngine.Hash(input));return result;}
  static bool Same(Dictionary<string,string>a,Dictionary<string,string>b){if(a.Count!=b.Count)return false;foreach(var pair in a)if(!b.ContainsKey(pair.Key)||b[pair.Key]!=pair.Value)return false;return true;}
  static int Published(string[] args){
   var fixture=new Fixture(args[1],args[2]);string version=args[3],work=args[2];var before=Snapshot(fixture.Root);var client=new UpdateClient("ArtVsTheWorld/DynastyCOT");var choices=client.Check();ReleaseChoice chosen=null;foreach(var choice in choices)if(choice.Version==version)chosen=choice;Check(chosen!=null,"explicit published candidate absent");var metadata=client.Inspect(chosen);Check(metadata.Version==version,"published version mismatch");var update=client.Download(metadata,Path.Combine(work,"downloads"),null);Check(Same(before,Snapshot(fixture.Root)),"published download changed installation");
   var modules=new Dictionary<string,bool>();foreach(string id in InstallerEngine.ModuleIds)modules.Add(id,true);using(var engine=new InstallerEngine()){
    var result=engine.Run(fixture.Root,modules,null,fixture,s=>{},"Install",update);Check(result.Success,"published candidate fixture install failed: "+result.Details);Check(InstallerEngine.InstalledVersion(fixture.Root)==version,"published install receipt mismatch");
    string history=Path.Combine(fixture.Root,"COT-Runtime","DynastyEnhancer","RuntimeHistory","701","history.json");Directory.CreateDirectory(Path.GetDirectoryName(history));File.WriteAllText(history,"published fixture user history");var backup=InstallerEngine.Backups(fixture.Root)[0];result=engine.Run(fixture.Root,modules,backup.Path,fixture,s=>{});Check(result.Success,"published rollback failed: "+result.Details);Check(File.ReadAllText(history)=="published fixture user history","published rollback lost history");File.Delete(history);Directory.Delete(Path.GetDirectoryName(history));Check(Same(before,Snapshot(fixture.Root)),"published install/rollback did not restore fixture");
   }File.WriteAllText(Path.Combine(work,"result.json"),new JavaScriptSerializer().Serialize(new{checks=checks,version=version,liveInstall=false,anonymousGitHub=true,explicitVersion=true,archiveSha256=metadata.ArchiveSha256,discoveryDownloadInstallRollback=true}));Console.WriteLine("PASS: "+checks+" anonymous published release checks; installation only in fixture.");return 0;
  }
  public static int Main(string[] args){try{if(args.Length==4&&args[0]=="--published")return Published(args);
   var fixture=new Fixture(args[0],args[1]);var config=Read(args[2]);string origin=(string)config["origin"],version=(string)config["version"],oldVersion=(string)config["oldVersion"],work=Path.GetDirectoryName(args[2]);
   var before=Snapshot(fixture.Root);var client=new UpdateClient("ArtVsTheWorld/DynastyCOT",new Uri(origin+"/releases"),fixture);
   var choices=client.Check();Check(choices.Count==2,"eligible releases, older and prerelease");Check(choices[0].Version==version&&choices[0].Prerelease,"public test prerelease label");Check(choices[1].Version==oldVersion,"older release retained");Check(Same(before,Snapshot(fixture.Root)),"check touched installation");
   var current=client.Inspect(choices[0]);Check(current.Notes.Contains("Candidate notes")&&current.Compatibility.Contains("Live acceptance pending"),"notes or compatibility lost");Check(Same(before,Snapshot(fixture.Root)),"inspect touched installation");
   foreach(object value in (System.Collections.IEnumerable)config["failures"]){string name=(string)value;bool rejected=false;try{var metadata=client.Inspect(new ReleaseChoice{Version=version,MetadataUrl=origin+"/meta/"+name});var update=client.Download(metadata,Path.Combine(work,"bad-"+name),null);using(var engine=new InstallerEngine())engine.ExtractUpdate(update,s=>{});}catch(Exception){rejected=true;}Check(rejected,"unsafe update accepted: "+name);Check(Same(before,Snapshot(fixture.Root)),"failure changed installation: "+name);Check(!Directory.Exists(Path.Combine(work,"bad-"+name))||Directory.GetFiles(Path.Combine(work,"bad-"+name),"*.part").Length==0,"partial file retained: "+name);}
   foreach(string path in new[]{"/forbidden","/missing","/server-error","/invalid-json","/redirect-outside","/redirect-loop"}){bool rejected=false;try{new UpdateClient("ArtVsTheWorld/DynastyCOT",new Uri(origin+path),fixture).Check();}catch(Exception){rejected=true;}Check(rejected,"server failure accepted: "+path);Check(Same(before,Snapshot(fixture.Root)),"server failure changed installation");}
   bool guard=false;try{new UpdateClient("ArtVsTheWorld/DynastyCOT",new Uri("http://example.com/releases"),fixture);}catch(IOException){guard=true;}Check(guard,"nonloopback fixture endpoint accepted");
   var verified=client.Download(current,Path.Combine(work,"downloads"),null);Check(Same(before,Snapshot(fixture.Root)),"download installed without action");
   using(var engine=new InstallerEngine()){
    string extracted=engine.ExtractUpdate(verified,s=>{});string script=Path.Combine(extracted,"Install.ps1"),original=File.ReadAllText(script);File.AppendAllText(script,"\n# modified fixture");bool rejected=false;try{engine.ExtractUpdate(verified,s=>{});}catch(IOException){rejected=true;}Check(rejected,"cached extraction tampering accepted");File.WriteAllText(script,original,new System.Text.UTF8Encoding(false));
   }
   string modified=Path.Combine(work,"changed.zip");File.Copy(verified.Archive,modified);using(var stream=new FileStream(modified,FileMode.Append))stream.WriteByte(0);bool changed=false;try{using(var engine=new InstallerEngine())engine.ExtractUpdate(new VerifiedUpdate(current,modified),s=>{});}catch(IOException){changed=true;}Check(changed,"changed archive accepted");
   var modules=new Dictionary<string,bool>();foreach(string id in InstallerEngine.ModuleIds)modules.Add(id,id!="DrivePractice");
   using(var engine=new InstallerEngine()){
    var old=client.Download(client.Inspect(choices[1]),Path.Combine(work,"downloads"),null);var result=engine.Run(fixture.Root,modules,null,fixture,s=>{},"Install",old);Check(result.Success,"older install failed: "+result.Details);Check(InstallerEngine.InstalledVersion(fixture.Root)==oldVersion,"older version receipt");
    var oldSnapshot=Snapshot(fixture.Root);modules["DrivePractice"]=true;result=engine.Run(fixture.Root,modules,null,fixture,s=>{},"Install",verified);Check(result.Success,"candidate install failed: "+result.Details);Check(InstallerEngine.InstalledVersion(fixture.Root)==version,"candidate receipt");Check(InstallerEngine.LoadModules(fixture.Root)["DrivePractice"],"selected modules lost");
    string history=Path.Combine(fixture.Root,"COT-Runtime","DynastyEnhancer","RuntimeHistory","701","history.json");Directory.CreateDirectory(Path.GetDirectoryName(history));File.WriteAllText(history,"published history survives updates and rollback");
    string settings=Path.Combine(fixture.Root,"Plugins","DynastyCOT","settings.json");string saved=File.ReadAllText(settings);File.AppendAllText(settings,"\n ");
    var backups=InstallerEngine.Backups(fixture.Root);Check(backups.Count>=2,"backup list missing transactions");result=engine.Run(fixture.Root,modules,backups[0].Path,fixture,s=>{});Check(result.Success,"rollback failed: "+result.Details);Check(InstallerEngine.InstalledVersion(fixture.Root)==oldVersion,"rollback receipt");Check(File.ReadAllText(history)=="published history survives updates and rollback","rollback destroyed history");Check(File.ReadAllText(settings)==saved+"\n ","rollback replaced later user settings");Check(File.ReadAllText(Path.Combine(fixture.Root,"Plugins","OtherOverhaul.dll"))=="unrelated overhaul","other mod changed");
    string host=Path.Combine(fixture.Root,"Plugins","DynastyCOT.dll");File.AppendAllText(host,"changed managed file");var snapshot=Snapshot(fixture.Root);result=engine.Run(fixture.Root,modules,InstallerEngine.Backups(fixture.Root)[0].Path,fixture,s=>{});Check(!result.Success,"managed conflict rollback accepted");Check(Same(snapshot,Snapshot(fixture.Root)),"failed rollback touched files");
   }
   File.WriteAllText(Path.Combine(work,"result.json"),new JavaScriptSerializer().Serialize(new{checks=checks,version=version,oldVersion=oldVersion,liveInstall=false,discoveryDownloadInstallRollback=true}));Console.WriteLine("PASS: "+checks+" updater checks, fixture only.");return 0;
  }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
 }
}

